import React, {Suspense, lazy, useEffect, useMemo, useRef, useState} from 'react';
const Admin=lazy(()=>import('./Admin'));
import {createRoot} from 'react-dom/client';
import {supabase, arrivedFromPasswordReset} from './supabase';
import * as api from './data';
import {money, CategoryIcon} from './shared';
import {Search, UserRound, ShoppingBag, Menu, X, ChevronRight, Heart, Gift, Camera, CakeSlice, Sparkles, Truck, ShieldCheck, Headphones, ArrowRight, Minus, Plus, Trash2, CheckCircle2, Clock3, PackageCheck, MapPin, Phone, Mail, Upload, Image as ImageIcon, FolderPlus, Settings, Download, Eye, LogOut} from 'lucide-react';
import './styles.css';
import logo from './assets/swetha-logo.webp';
import {EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, EMAILJS_PUBLIC_KEY, NOTIFY_EMAIL} from './emailjs';

const WHATSAPP_NUMBER='918838629847';

const PATHS={home:'/',shop:'/shop',cart:'/cart',checkout:'/checkout',track:'/track',account:'/account',about:'/about',contact:'/contact',privacy:'/privacy',terms:'/terms',admin:'/admin'};
const PAGE_META={home:['Swetha Handmades — Handmade & Personalised Gifts','Handmade gift hampers, candles, photo albums and personalised keepsakes, made with love in India. Order online, pay later on WhatsApp.'],shop:['Shop Handmade Gifts | Swetha Handmades','Browse handmade gift hampers, candles, photo albums and personalised gifts for birthdays, anniversaries and every special moment.'],cart:['Your Cart | Swetha Handmades'],checkout:['Checkout | Swetha Handmades'],track:['Track Your Order | Swetha Handmades','Check your Swetha Handmades order status with your order ID and mobile number. No login needed.'],account:['My Account | Swetha Handmades'],about:['About Us | Swetha Handmades','Every box, album and keepsake is thoughtfully put together by hand at Swetha Handmades.'],contact:['Contact Us | Swetha Handmades','Reach Swetha Handmades on WhatsApp or Instagram for custom orders and questions.'],privacy:['Privacy Policy | Swetha Handmades','How Swetha Handmades collects, uses and protects your personal data.'],terms:['Terms & Conditions | Swetha Handmades','Terms for ordering handmade and personalised gifts from Swetha Handmades: payment, delivery, cancellations and refunds.'],admin:['Admin | Swetha Handmades'],notfound:['Page Not Found | Swetha Handmades']};
function viewFromPath(path){const p=path.replace(/\/+$/,'')||'/';if(/^\/product\/[0-9a-f-]{36}$/i.test(p))return 'product';const v=Object.keys(PATHS).find(k=>PATHS[k]===p);return v||'notfound'}
const productIdFromPath=path=>(path.match(/^\/product\/([0-9a-f-]{36})\/?$/i)||[])[1]||null;
function contactError({mobile,email,pincode}){const d=String(mobile||'').replace(/[^0-9]/g,'');if(mobile&&(d.length<10||d.length>15))return 'Please enter a valid mobile number (10 digits)';if(email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email.trim()))return 'Please enter a valid email address';if(pincode&&!/^[0-9]{6}$/.test(pincode.trim()))return 'Pincode should be 6 digits';return ''}
const HERO_SIZES='(max-width: 700px) 310px, (max-width: 1000px) 430px, 510px';
const occasions=['Birthdays','Anniversaries','Weddings','Festivals','Just Because'];
const confetti=['rect','dot','heart','diamond','star'];
function load(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){console.warn('Local storage limit reached',e)}}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
function WhatsIcon({size=18}){return <svg width={size} height={size} viewBox="0 0 32 32" fill="currentColor" aria-hidden="true"><path d="M16.04 4c-6.6 0-11.96 5.36-11.96 11.96 0 2.11.55 4.09 1.52 5.8L4 28l6.42-1.53a11.9 11.9 0 0 0 5.62 1.42h.01c6.6 0 11.96-5.36 11.96-11.96S22.64 4 16.04 4zm7.03 17.13c-.3.85-1.75 1.63-2.4 1.72-.63.1-1.4.14-2.26-.14-.52-.17-1.19-.39-2.06-.76-3.63-1.57-6-5.21-6.18-5.46-.18-.24-1.47-1.96-1.47-3.74s.93-2.65 1.26-3.02c.33-.36.72-.45.96-.45h.69c.22 0 .52-.01.81.62.3.65 1.02 2.24 1.11 2.4.09.16.15.35.03.56-.12.21-.18.34-.36.53-.18.19-.38.42-.54.57-.18.17-.37.35-.16.68.21.34.94 1.55 2.02 2.51 1.38 1.24 2.55 1.63 2.9 1.81.35.18.55.15.75-.09.21-.24.9-1.04 1.14-1.4.24-.35.48-.29.8-.17.33.12 2.1.99 2.46 1.17.36.18.6.27.68.42.09.15.09.86-.22 1.7z"/></svg>}
function WhatsAppButton(){return <a className="whatsappFloat" href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer" aria-label="Chat with us on WhatsApp"><WhatsIcon size={30}/></a>}
function SignupPopup({go,account}){const [show,setShow]=useState(false);useEffect(()=>{if(account)return;let shown=false;try{shown=sessionStorage.getItem('sh_signup_popup')==='1'}catch(e){}if(shown)return;const t=setTimeout(()=>{setShow(true);try{sessionStorage.setItem('sh_signup_popup','1')}catch(e){}},1600);return()=>clearTimeout(t)},[account]);if(!show||account)return null;return <div className="signupPopup" onClick={()=>setShow(false)}><div className="signupPopupCard" onClick={e=>e.stopPropagation()}><button className="popupClose" onClick={()=>setShow(false)} aria-label="Close">×</button><Sparkles size={26}/><h3>Join Swetha Handmades ♥</h3><p>Sign up to track your orders easily and hear about new handmade collections first.</p><button className="primary wide" onClick={()=>{setShow(false);go('account')}}>Sign Up Now</button><button className="textBtn" onClick={()=>setShow(false)}>Maybe later</button></div></div>}
function Confetti({count=26}){return <div className="confetti" aria-hidden="true">{Array.from({length:count},(_,i)=><span key={i} className={confetti[i%confetti.length]} style={{left:`${(i*37)%101}%`,top:`${(i*53)%101}%`,transform:`rotate(${(i*31)%360}deg)`,animationDelay:`-${(i%7)*.7}s`}} />)}</div>}
function InstaIcon({size=18}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".7" fill="currentColor" stroke="none"/></svg>}

function App(){
 const [cachedCatalogue]=useState(()=>load('sh_catalogue',null));
 const [products,setProducts]=useState(()=>cachedCatalogue?.products||[]);
 const [categories,setCategories]=useState(()=>cachedCatalogue?.categories||[]);
 const [orders,setOrders]=useState([]);
 const [cart,setCart]=useState(()=>load('sh_cart',[]));
 const [settings,setSettings]=useState(()=>cachedCatalogue?.settings||{instagram:api.DEFAULT_INSTAGRAM,heroImage:api.imageUrl(api.HERO_PATH),heroSm:api.imageUrl(api.thumbPath(api.HERO_PATH)),heroPath:api.HERO_PATH});
 const [recovery,setRecovery]=useState(arrivedFromPasswordReset);
 const [view,setView]=useState(()=>arrivedFromPasswordReset?'account':viewFromPath(window.location.pathname)), [selected,setSelected]=useState(null), [category,setCategory]=useState('All Products'), [queryText,setQueryText]=useState(''), [menu,setMenu]=useState(false), [account,setAccount]=useState(null), [toast,setToast]=useState('');
 const [user,setUser]=useState(null), [sessionReady,setSessionReady]=useState(false), [catalogueReady,setCatalogueReady]=useState(!!cachedCatalogue), [loadError,setLoadError]=useState(''), [isAdmin,setIsAdmin]=useState(false);
 const userId=user?.id;
 const reloadCatalogue=async()=>{const c=await api.loadCatalogue();setProducts(c.products);setCategories(c.categories);setSettings(c.settings);save('sh_catalogue',c);return c};
 const reloadOrders=async()=>{if(!userId){setOrders([]);return}try{setOrders(await api.loadOrders())}catch(e){console.error('Could not load orders',e)}};
 useEffect(()=>{supabase.auth.getSession().then(({data})=>{setUser(data.session?.user??null);setSessionReady(true)});const {data:{subscription}}=supabase.auth.onAuthStateChange((event,session)=>{setUser(session?.user??null);if(event==='PASSWORD_RECOVERY'){setRecovery(true);setView('account')}});return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{reloadCatalogue().then(c=>{const byId=new Map(c.products.map(p=>[p.id,p]));setCart(items=>items.filter(i=>byId.has(i.id)).map(i=>({...byId.get(i.id),qty:Math.min(99,Math.max(1,Number(i.qty)||1)),custom:i.custom||null})));setCatalogueReady(true)}).catch(e=>{console.error('Could not load the shop',e);setLoadError('We could not load the shop right now. Please refresh the page.')})},[]);
 // A signed-in user from the other site sharing this Supabase project is not a Swetha customer (guide §4).
 useEffect(()=>{if(!userId){setAccount(null);setIsAdmin(false);setOrders([]);return}if(user.app_metadata?.site!=='swetha'){supabase.auth.signOut({scope:'local'});return}let live=true;(async()=>{try{const [profile,admin]=await Promise.all([api.loadOrCreateProfile(user),api.isAdmin()]);if(!live)return;setAccount({uid:user.id,name:profile.full_name||'Customer',email:user.email||'',mobile:profile.phone||''});setIsAdmin(admin)}catch(e){console.error('Could not load your account',e);if(live){setAccount({uid:user.id,name:'Customer',email:user.email||'',mobile:''});setIsAdmin(false)}}})();return()=>{live=false}},[userId]);
 useEffect(()=>{if(!userId)return;reloadOrders();if(!isAdmin)return;const channel=supabase.channel('swetha:orders').on('postgres_changes',{event:'*',schema:'swetha',table:'orders'},()=>reloadOrders()).subscribe();return()=>{supabase.removeChannel(channel)}},[userId,isAdmin]);
 useEffect(()=>save('sh_cart',cart),[cart]);
 useEffect(()=>{const onPop=()=>{setSelected(null);setView(viewFromPath(window.location.pathname))};window.addEventListener('popstate',onPop);return()=>window.removeEventListener('popstate',onPop)},[]);
 // A product page opened directly by its address: find the product once the catalogue has loaded.
 useEffect(()=>{if(view!=='product'||selected||!catalogueReady)return;const p=products.find(x=>x.id===productIdFromPath(window.location.pathname));if(p)setSelected(p);else setView('notfound')},[view,selected,catalogueReady,products]);
 useEffect(()=>{const [title,desc]=view==='product'&&selected?[`${selected.name} | Swetha Handmades`,(selected.desc||PAGE_META.home[1]).slice(0,160)]:(PAGE_META[view]||PAGE_META.home);document.title=title;document.querySelector('meta[name=description]')?.setAttribute('content',desc||PAGE_META.home[1]);document.querySelector('link[rel=canonical]')?.setAttribute('href',window.location.origin+window.location.pathname)},[view,selected]);
 const go=(v,productId)=>{setView(v);setMenu(false);try{const path=v==='product'&&productId?`/product/${productId}`:(PATHS[v]||'/');if(window.location.pathname!==path)history.pushState({},'',path)}catch(e){}window.scrollTo({top:0,behavior:'smooth'})};
 const flash=m=>{setToast(m);setTimeout(()=>setToast(''),2200)};
 const add=(p,options={})=>{setCart(c=>[...c,{...p,qty:1,custom:options.custom||null,photos:options.photos||[]}]);flash('Added to your cart ♥')};
 const filtered=useMemo(()=>products.filter(p=>(category==='All Products'||p.category===category)&&(!queryText||p.name.toLowerCase().includes(queryText.toLowerCase()))),[products,category,queryText]);
 const cartCount=cart.reduce((s,p)=>s+p.qty,0);
 if(!sessionReady||(!catalogueReady&&view!=='home'))return <div className="app"><div className="page wrap" style={{minHeight:'70vh',display:'grid',placeItems:'center'}}><div className="empty">{loadError||'Loading Swetha Handmades…'}</div></div></div>;
 return <div className="app">
  {view!=='admin'&&<><div className="announcement"><span>Handmade with Love</span><b>♥</b><span>For Life's Special Moments</span><b>✦</b><a className="socialMini" href={settings.instagram} target="_blank" rel="noreferrer"><InstaIcon size={14}/> Instagram</a></div><Header go={go} cartCount={cartCount} query={queryText} setQuery={setQueryText} menu={menu} setMenu={setMenu} view={view} instagram={settings.instagram}/></>}
  {view==='home'&&<Home go={go} setCategory={setCategory} products={products} add={add} categories={categories} settings={settings} open={p=>{setSelected(p);go('product',p.id)}}/>}
  {view==='shop'&&<Shop products={filtered} categories={categories} category={category} setCategory={setCategory} query={queryText} setQuery={setQueryText} add={add} open={p=>{setSelected(p);go('product',p.id)}}/>}
  {view==='product'&&selected&&<Product p={selected} add={add} back={()=>go('shop')} instagram={settings.instagram}/>}
  {view==='contact'&&<Contact instagram={settings.instagram}/>}
  {view==='cart'&&<Cart cart={cart} setCart={setCart} go={go}/>}
  {view==='checkout'&&<Checkout cart={cart} setCart={setCart} go={go} flash={flash} account={account} onPlaced={reloadOrders} instagram={settings.instagram}/>}
  {view==='track'&&<Track instagram={settings.instagram} flash={flash}/>}
  {view==='account'&&<Account account={account} setAccount={setAccount} orders={orders} go={go} flash={flash} recovery={recovery} setRecovery={setRecovery}/>} 
  {view==='about'&&<About go={go}/>}
  {view==='privacy'&&<Privacy/>}
  {view==='terms'&&<Terms go={go}/>} 
  {view==='admin'&&<Suspense fallback={<div className="page wrap"><div className="empty">Loading admin…</div></div>}><Admin products={products} categories={categories} orders={orders} settings={settings} setSettings={setSettings} go={go} flash={flash} isAdmin={isAdmin} reloadCatalogue={reloadCatalogue} reloadOrders={reloadOrders}/></Suspense>}
  {view==='notfound'&&<NotFound go={go}/>}
  {view!=='admin'&&<Footer go={go} instagram={settings.instagram} categories={categories} setCategory={setCategory}/>}
  {view!=='admin'&&<WhatsAppButton/>}
  {view!=='admin'&&<SignupPopup go={go} account={account}/>}
  {toast&&<div className="toast">{toast}</div>}
 </div>
}

function Header({go,cartCount,query,setQuery,menu,setMenu,view,instagram}){return <header className="header"><div className="nav wrap"><button className="icon mobileOnly" onClick={()=>setMenu(!menu)} aria-label={menu?'Close menu':'Open menu'} aria-expanded={menu}>{menu?<X/>:<Menu/>}</button><button className="brand brandImage" onClick={()=>go('home')} aria-label="Swetha Handmades home"><img src={logo} alt="Swetha Handmades"/></button><nav className={menu?'open':''}><button className={view==='home'?'active':''} onClick={()=>go('home')}>Home</button><button className={view==='shop'||view==='product'?'active':''} onClick={()=>go('shop')}>Shop</button><button className={view==='track'?'active':''} onClick={()=>go('track')}>Track Order</button><button className={view==='about'?'active':''} onClick={()=>go('about')}>About</button><button className={view==='contact'?'active':''} onClick={()=>go('contact')}>Contact</button></nav><div className="navActions"><div className="search"><Search size={17}/><input placeholder="Search gifts..." value={query} onChange={e=>setQuery(e.target.value)} onFocus={()=>go('shop')}/></div><button className="circle" onClick={()=>go('account')} aria-label="Account"><UserRound size={19}/></button><button className="cartBtn" onClick={()=>go('cart')} aria-label={`Cart, ${cartCount} items`}><ShoppingBag size={20}/><i>{cartCount}</i></button></div></div></header>}

function Home({go,setCategory,products,add,categories,settings,open}){return <>
 <section className="hero"><Confetti count={42}/><div className="heroGrid wrap"><div className="heroCopy"><span className="eyebrow">HANDMADE • PERSONAL • HEARTFELT</span><h1>Thoughtful Gifts<br/><em>for Every Special Moment</em></h1><p>Customised gifts, hampers, memory keepsakes and more — all handmade with love.</p><button className="primary" onClick={()=>go('shop')}>Shop Now <ArrowRight size={18}/></button><div className="benefits"><Benefit icon={Gift} text="Unique Handmade Gifts"/><Benefit icon={Heart} text="Customised Just for You"/><Benefit icon={Truck} text="Safe & Secure Delivery"/><Benefit icon={ShieldCheck} text="Made with Love"/></div></div><div className="heroVisual"><div className="heroBlob"></div><div className="heroPhoto"><img src={settings?.heroImage||products[0]?.image} srcSet={settings?.heroImage&&settings?.heroSm?`${settings.heroSm} 640w, ${settings.heroImage} 1200w`:undefined} sizes={HERO_SIZES} alt="Handmade gifts by Swetha Handmades" fetchPriority="high"/><div className="photoNote">Good<br/>Things<br/>Take Time ♥</div><div className="photoTag">Handmade<br/>with Love ♡</div></div><div className="handText">Small<br/>Creations<br/><strong>Big<br/>Happiness</strong> ♡</div></div></div></section>
 <section className="categoryBand"><div className="wrap"><div className="sectionIntro centered"><span className="eyebrow">EXPLORE OUR CREATIONS</span><h2>Shop by Category</h2><button className="textBtn" onClick={()=>{setCategory('All Products');go('shop')}}>View All Categories <ArrowRight size={15}/></button></div><div className="categoryRow">{categories.map(c=><button key={c.name} className="categoryTile" onClick={()=>{setCategory(c.name);go('shop')}}><span className={`catIcon ${c.tone}`}><CategoryIcon type={c.icon}/></span><b>{c.name}</b></button>)}<button className="categoryTile" onClick={()=>go('shop')}><span className="catIcon blue"><ShoppingBag size={27}/></span><b>All Products</b></button></div></div></section>
 <section className="featured wrap"><div className="sectionIntro centered"><span className="eyebrow">FEATURED PRODUCTS</span><h2>Made with Love, Just for You</h2><p>Handpicked favourites from our collection</p><button className="textBtn" onClick={()=>{setCategory('All Products');go('shop')}}>View All <ArrowRight size={15}/></button></div><div className="productGrid">{products.slice(0,5).map(p=><ProductCard key={p.id} p={p} add={add} open={()=>open(p)}/>)}</div></section>
 <section className="instagramBand"><Confetti count={26}/><div className="wrap instagramInner"><div><span className="eyebrow">FOLLOW OUR JOURNEY</span><h2>More Handmade Happiness on Instagram</h2><p>See our latest creations, custom orders and gifting inspiration.</p></div><a className="outline" href={settings.instagram} target="_blank" rel="noreferrer"><InstaIcon size={18}/> Follow @swetha_handmades <ArrowRight size={18}/></a></div></section>
 <section className="occasion"><Confetti count={34}/><div className="occasionInner wrap"><div className="giftStack"><div>🎁</div><div>🎀</div></div><div><span className="eyebrow">CELEBRATE EVERY LITTLE THING</span><h2>Make Every Occasion Special</h2><p>{occasions.join(' • ')}</p><button className="outline" onClick={()=>go('shop')}>Shop Occasion Gifts <ArrowRight size={18}/></button></div><div className="occasionScript">Happiness<br/>Looks Good<br/>on You ♡</div></div></section>
 <section className="serviceStrip wrap"><Benefit icon={Truck} text="Fast & Reliable Delivery"/><Benefit icon={ShieldCheck} text="Secure Payments"/><Benefit icon={Heart} text="100% Handmade"/><Benefit icon={Headphones} text="Friendly Support"/></section>
 </>}
function Benefit({icon:Icon,text}){return <div className="benefit"><Icon size={25}/><span>{text}</span></div>}
function ProductCard({p,add,open}){return <article className="productCard"><button className="heartBtn" aria-label="Wishlist"><Heart size={18}/></button><div className="pImg" onClick={open}><img src={p.thumb||p.image} alt={p.name} loading="lazy" onError={e=>{if(p.image&&e.currentTarget.src!==p.image)e.currentTarget.src=p.image}}/>{p.badge&&<span>{p.badge}</span>}</div><div className="pInfo"><small>{p.category}</small><h3>{p.name}</h3><strong>{money(p.price)}</strong><button className="add" onClick={()=>add(p)}><ShoppingBag size={15}/> Add to Cart</button></div></article>}
function Shop({products,categories,category,setCategory,query,setQuery,add,open}){return <section className="page wrap"><div className="shopHeader"><div><span className="eyebrow">EXPLORE THE COLLECTION</span><h1>Gifts for Every Feeling</h1><p>Handmade pieces for the moments that matter.</p></div><div className="shopSearch"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search products"/></div></div><div className="chips"><button className={category==='All Products'?'active':''} onClick={()=>setCategory('All Products')}>All</button>{categories.map(c=><button key={c.name} className={category===c.name?'active':''} onClick={()=>setCategory(c.name)}>{c.name}</button>)}</div><div className="productGrid">{products.map(p=><ProductCard key={p.id} p={p} add={add} open={()=>open(p)}/>)}</div>{!products.length&&<div className="empty">No gifts found. Try another search.</div>}</section>}
function Product({p,add,back,instagram}){const [qty,setQty]=useState(1),[custom,setCustom]=useState({name:'',message:''});const gallery=(p.images&&p.images.length?p.images:[p.image]).filter(Boolean);const [activeImg,setActiveImg]=useState(0);return <section className="page wrap productPage"><button className="back" onClick={back}>← Back to shop</button><div className="productDetail"><div><div className="detailImage"><img src={gallery[activeImg]||p.image} alt={p.name}/></div>{gallery.length>1&&<div className="galleryThumbs">{gallery.map((img,i)=><button key={i} className={i===activeImg?'active':''} onClick={()=>setActiveImg(i)}><img src={p.thumbs?.[i]||img} alt={`${p.name} ${i+1}`} loading="lazy"/></button>)}</div>}</div><div className="detailCopy"><span className="eyebrow">{p.category}</span><h1>{p.name}</h1><div className="price">{money(p.price)}</div><p>{p.desc}</p><div className="personalBox"><b>Personalise your order ♥</b><p className="muted">Add a name or a message you'd like us to use while preparing your gift.</p><label>Name / Text<input value={custom.name} onChange={e=>setCustom({...custom,name:e.target.value})} placeholder="e.g. Our Journey" maxLength="200"/></label><label>Special Message<textarea value={custom.message} onChange={e=>setCustom({...custom,message:e.target.value})} placeholder="A message you'd like us to include" maxLength="500"/></label><div className="instaPhotoBox"><b>Upload your personalised photos</b><p>{p.personalised?`After you place your order, you can upload up to ${p.maxPhotos} photo${p.maxPhotos>1?'s':''} on the order confirmation page or from Track Order. You can also send them to us directly:`:"Place your order, then send us your photos directly for this gift and we'll personalise it exactly the way you'd like."}</p><div className="contactIconsRow"><a className="uploadBtn" href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer"><WhatsIcon size={16}/> WhatsApp</a><a className="uploadBtn" href={instagram} target="_blank" rel="noreferrer"><InstaIcon size={16}/> Instagram</a></div></div></div><div className="qty"><button onClick={()=>setQty(Math.max(1,qty-1))}><Minus size={15}/></button><b>{qty}</b><button onClick={()=>setQty(qty+1)}><Plus size={15}/></button></div><button className="primary wide" onClick={()=>{for(let i=0;i<qty;i++)add(p,{custom})}}>Add to Cart <ShoppingBag size={18}/></button></div></div></section>}
function Cart({cart,setCart,go}){const total=cart.reduce((s,p)=>s+p.price*p.qty,0);return <section className="page wrap cartPage"><span className="eyebrow">YOUR SELECTION</span><h1>Your Cart</h1>{!cart.length?<div className="empty">Your cart is waiting for something lovely. <button className="primary" onClick={()=>go('shop')}>Shop Gifts</button></div>:<div className="cartLayout"><div>{cart.map((p,i)=><div className="cartItem" key={p.id+'-'+i}><img src={p.thumb||p.image} alt={p.name} loading="lazy" onError={e=>{if(p.image&&e.currentTarget.src!==p.image)e.currentTarget.src=p.image}}/><div><small>{p.category}</small><h3>{p.name}</h3><strong>{money(p.price)}</strong>{p.photos?.length>0&&<small className="photoAttached">📸 {p.photos.length} photos attached</small>}</div><div className="cartQty"><button onClick={()=>setCart(c=>c.map((x,j)=>j===i?{...x,qty:Math.max(1,x.qty-1)}:x))}>−</button><b>{p.qty}</b><button onClick={()=>setCart(c=>c.map((x,j)=>j===i?{...x,qty:Math.min(99,x.qty+1)}:x))}>+</button></div><button className="remove" onClick={()=>setCart(c=>c.filter((_,j)=>j!==i))}><Trash2 size={17}/></button></div>)}</div><aside className="summary"><h2>Order Summary</h2><div><span>Subtotal</span><b>{money(total)}</b></div><div><span>Delivery</span><span>Calculated after order</span></div><hr/><div className="grand"><b>Total</b><strong>{money(total)}</strong></div><button className="primary wide" onClick={()=>go('checkout')}>Continue to Checkout <ArrowRight size={17}/></button><small>No advance payment needed — we'll get in touch with you directly for payment.</small></aside></div>}</section>}
const loadEmailJs=()=>window.emailjs?Promise.resolve(window.emailjs):new Promise((resolve,reject)=>{const el=document.createElement('script');el.src='https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js';el.onload=()=>resolve(window.emailjs);el.onerror=reject;document.head.appendChild(el)});
async function sendOrderEmail(o){if(!EMAILJS_SERVICE_ID||EMAILJS_SERVICE_ID.startsWith('YOUR_'))return;try{const emailjs=await loadEmailJs();await emailjs.send(EMAILJS_SERVICE_ID,EMAILJS_TEMPLATE_ID,{to_email:NOTIFY_EMAIL,order_id:o.id,customer_name:o.name,customer_mobile:o.mobile,customer_address:[o.address1,o.address2,o.landmark,o.city,o.pincode].filter(Boolean).join(', '),order_total:money(o.total),order_items:o.items.map(p=>`${p.name} x${p.qty}`).join(', ')},EMAILJS_PUBLIC_KEY)}catch(e){console.warn('Order email notification failed',e)}}
function Checkout({cart,setCart,go,flash,account,onPlaced,instagram}){const [form,setForm]=useState({name:account?.name||'',mobile:account?.mobile||'',email:account?.email||'',address1:'',address2:'',landmark:'',city:'',pincode:'',notes:''}),[done,setDone]=useState(null),[busy,setBusy]=useState(false),[website,setWebsite]=useState(''),[tsToken,setTsToken]=useState('');const tsBox=useRef(null),tsWidget=useRef(null);useEffect(()=>{if(done||!api.TURNSTILE_SITE_KEY)return;let live=true;api.loadTurnstile().then(ts=>{if(!live||!tsBox.current||tsWidget.current!==null)return;tsWidget.current=ts.render(tsBox.current,{sitekey:api.TURNSTILE_SITE_KEY,appearance:'interaction-only',callback:t=>setTsToken(t),'expired-callback':()=>setTsToken(''),'error-callback':()=>setTsToken('')})}).catch(e=>console.error(e));return()=>{live=false;if(tsWidget.current!==null){try{window.turnstile?.remove(tsWidget.current)}catch{}tsWidget.current=null}}},[done]);const total=cart.reduce((s,p)=>s+p.price*p.qty,0);const change=e=>setForm({...form,[e.target.name]:e.target.value});const submit=async e=>{e.preventDefault();if(!form.name.trim()||!form.mobile.trim()||!form.address1.trim()){flash('Please complete the required details');return}const bad=contactError(form);if(bad){flash(bad);return}setBusy(true);if(!tsToken){flash('Just a moment, checking you are human… please try again');return}try{const res=await api.placeOrder(form,cart,{turnstileToken:tsToken,website});const placed={id:res.code,...form,items:cart.map(p=>({name:p.name,qty:p.qty})),total:res.total,status:'Received',createdAt:res.createdAt};setDone(placed);setCart([]);sendOrderEmail(placed);if(account)onPlaced()}catch(err){console.error(err);flash(err.message||'Could not place the order');setTsToken('');try{if(tsWidget.current!==null)window.turnstile?.reset(tsWidget.current)}catch{}}finally{setBusy(false)}};if(done)return <section className="page wrap success"><div className="successCard"><CheckCircle2 size={58}/><span className="eyebrow">ORDER RECEIVED</span><h1>Thank you, {done.name}!</h1><p>Your order has been placed successfully. We'll reach out to you directly to arrange payment.</p><div className="orderCode">{done.id}</div><PhotoUpload code={done.id} mobile={done.mobile}/><SendPhotosVia order={done} instagram={instagram} flash={flash}/><p>Use your order ID and mobile number on <b>Track Order</b> to check the status anytime.</p><button className="primary" onClick={()=>go('track')}>Track My Order <ArrowRight size={17}/></button></div></section>;
 return <section className="page wrap"><div className="checkoutHead"><div><span className="eyebrow">ALMOST THERE</span><h1>Place Your Order</h1><p>{account?'Your order will be securely saved to your account.':'No account or login is required. Your order will be securely saved for tracking.'}</p></div></div><form className="checkoutGrid" onSubmit={submit}><div className="formCard"><h2>Your Details</h2><div className="two"><label>Name *<input name="name" value={form.name} onChange={change} required maxLength="100" autoComplete="name"/></label><label>Mobile Number *<input name="mobile" type="tel" inputMode="tel" value={form.mobile} onChange={change} required maxLength="20" autoComplete="tel" placeholder="10-digit mobile"/></label></div><div className="two"><label>Email <input name="email" type="email" value={form.email} onChange={change} maxLength="254" autoComplete="email"/></label><label>Pincode <input name="pincode" inputMode="numeric" pattern="[0-9]{6}" title="6-digit pincode" value={form.pincode} onChange={change} maxLength="6" autoComplete="postal-code"/></label></div><label>Address Line 1 *<input name="address1" value={form.address1} onChange={change} placeholder="House / flat no., street" required maxLength="300" autoComplete="address-line1"/></label><label>Address Line 2<input name="address2" value={form.address2} onChange={change} placeholder="Area, locality (optional)" maxLength="300" autoComplete="address-line2"/></label><label>Landmark<input name="landmark" value={form.landmark} onChange={change} placeholder="Nearby landmark (optional)" maxLength="200"/></label><label>City <input name="city" value={form.city} onChange={change} maxLength="100" autoComplete="address-level2"/></label><label>Order Notes / Personalisation<textarea name="notes" value={form.notes} onChange={change} placeholder="Name to add, message, colour preference, etc." maxLength="1000"/></label></div><aside className="summary"><h2>Order Summary</h2>{cart.map((p,i)=><div key={i}><span>{p.name} × {p.qty}</span><b>{money(p.price*p.qty)}</b></div>)}<hr/><div className="grand"><b>Total</b><strong>{money(total)}</strong></div><p className="paymentNote">No payment needed right now — we'll contact you directly to arrange payment after your order is placed.</p><p className="paymentNote">By placing an order you agree to our <button type="button" className="textBtn" onClick={()=>go('terms')}>Terms</button>. We use your details only for this order (see our <button type="button" className="textBtn" onClick={()=>go('privacy')}>Privacy Policy</button>).</p><input className="hpField" name="website" value={website} onChange={e=>setWebsite(e.target.value)} tabIndex="-1" autoComplete="off" aria-hidden="true"/><div ref={tsBox} className="turnstileBox"/><button className="primary wide" type="submit" disabled={busy}>{busy?'Placing Order…':<>Place Order <CheckCircle2 size={17}/></>}</button></aside></form></section>}
function Track({instagram,flash}){const [id,setId]=useState(''),[mobile,setMobile]=useState(''),[found,setFound]=useState(null),[searched,setSearched]=useState(false),[busy,setBusy]=useState(false),[foundMobile,setFoundMobile]=useState('');const check=async()=>{if(!id.trim()||!mobile.trim())return;setBusy(true);try{setFound(await api.trackOrder(id,mobile));setFoundMobile(mobile)}catch(e){console.error(e);setFound(null)}finally{setSearched(true);setBusy(false)}};const statuses=['Received','Confirmed','Preparing','Ready','Delivered'];const idx=found?statuses.indexOf(found.status):-1;return <section className="page wrap trackPage"><span className="eyebrow">ORDER TRACKING</span><h1>Track Your Order</h1><p>Enter your order ID and mobile number. No login required.</p><div className="trackForm"><input placeholder="Order ID e.g. SH123456" value={id} onChange={e=>setId(e.target.value)}/><input placeholder="Mobile Number" type="tel" inputMode="tel" maxLength="20" value={mobile} onChange={e=>setMobile(e.target.value)}/><button className="primary" onClick={check} disabled={busy}>{busy?'Checking…':'Check Status'}</button></div>{found?<div className="trackCard"><div className="trackTitle"><div><small>{found.id}</small><h2>Order status: {found.status}</h2></div><span>{new Date(found.createdAt).toLocaleDateString('en-IN')}</span></div><div className="timeline">{statuses.map((s,i)=><div className={i<=idx?'done':''} key={s}><span>{i<idx?'✓':i===idx?'●':'○'}</span><b>{s}</b></div>)}</div><div className="trackItems">{found.items.map((p,i)=><div key={i}><span>{p.name} × {p.qty}</span><b>{money(p.price*p.qty)}</b></div>)}</div><PhotoUpload code={found.id} mobile={foundMobile}/>{!['Delivered','Cancelled'].includes(found.status)&&<SendPhotosVia order={found} instagram={instagram} flash={flash}/>}</div>:searched&&<div className="empty">We couldn't find that order. Please check the Order ID and mobile number.</div>}</section>}
function Account({account,setAccount,orders,go,flash,recovery,setRecovery}){const [mode,setMode]=useState('login'),[form,setForm]=useState({name:'',mobile:'',email:'',password:''}),[busy,setBusy]=useState(false),[newPw,setNewPw]=useState({a:'',b:''});if(recovery)return <section className="page authPage"><div className="authCard"><span className="eyebrow">RESET PASSWORD</span><h1>Set a New Password</h1><p>Choose a new password for your account.</p><form onSubmit={async e=>{e.preventDefault();if(newPw.a.length<6){flash('Password must be at least 6 characters');return}if(newPw.a!==newPw.b){flash('The two passwords do not match');return}setBusy(true);try{await api.setNewPassword(newPw.a);setRecovery(false);setNewPw({a:'',b:''});flash('Password updated ♥')}catch(err){console.error(err);flash(/different from the old/i.test(err.message||'')?'Please choose a password different from your old one':'Could not update the password. The reset link may have expired, so please request a new one.')}finally{setBusy(false)}}}><input type="password" placeholder="New password" value={newPw.a} onChange={e=>setNewPw({...newPw,a:e.target.value})} required minLength="6"/><input type="password" placeholder="Confirm new password" value={newPw.b} onChange={e=>setNewPw({...newPw,b:e.target.value})} required minLength="6"/><button className="primary wide" disabled={busy}>{busy?'Please wait…':'Save New Password'}</button></form></div></section>;if(account)return <section className="page wrap accountPage"><span className="eyebrow">MY SWETHA HANDMADES</span><h1>Hello, {(account.name||'Customer').split(' ')[0]} ♥</h1><div className="accountGrid"><div className="profile"><UserRound size={35}/><h3>{account.name}</h3><p>{account.mobile||'Mobile not added'}</p><p>{account.email}</p><button className="outline" onClick={async()=>{await supabase.auth.signOut();setAccount(null);flash('Logged out ♥')}}>Log out</button><button className="textBtn" onClick={async()=>{if(window.prompt('This permanently deletes your account. Your past orders stay with the shop for its records but are no longer linked to you. Type DELETE to confirm.')!=='DELETE')return;try{await api.deleteMyAccount();setAccount(null);flash('Your account has been deleted')}catch(e){console.error(e);flash(e.message)}}}>Delete my account</button></div><div><h2>My Orders</h2>{orders.length?orders.map(o=><div className="orderRow" key={o.id}><div><b>{o.id}</b><small>{new Date(o.createdAt).toLocaleDateString('en-IN')}</small></div><strong>{money(o.total)}</strong><span>{o.status}</span></div>):<div className="empty">No orders yet. <button className="textBtn" onClick={()=>go('shop')}>Start shopping</button></div>}</div></div></section>;const change=e=>setForm({...form,[e.target.name]:e.target.value});const submit=async e=>{e.preventDefault();if(mode==='forgot'){if(!form.email.trim()){flash('Please enter your email');return}setBusy(true);try{await api.sendPasswordReset(form.email)}catch(err){console.error(err)}finally{setBusy(false)}flash("If that email has an account, we've sent a reset link ♥");setMode('login');return}if(!form.email||!form.password){flash('Email and password are required');return}if(mode==='signup'){const bad=contactError({mobile:form.mobile,email:form.email});if(bad){flash(bad);return}}setBusy(true);try{if(mode==='signup'){const {data,error}=await supabase.auth.signUp({email:form.email.trim(),password:form.password,options:{emailRedirectTo:window.location.origin+'/',data:{full_name:form.name.trim(),phone:form.mobile.trim(),site:'swetha'}}});if(error)throw error;if(data.session)flash('Account created ♥');else{flash('Check your email to confirm your account ♥');setMode('login')}}else{const {error}=await supabase.auth.signInWithPassword({email:form.email.trim(),password:form.password});if(error)throw error;flash('Welcome back ♥')}}catch(err){const m=String(err.message||'');const msg=/invalid login credentials/i.test(m)?'Incorrect email or password':/email not confirmed/i.test(m)?'Please confirm your email first. Check your inbox.':/already registered/i.test(m)?'An account already exists with this email':/password/i.test(m)?'Password must be at least 6 characters':m||'Something went wrong. Please try again.';flash(msg)}finally{setBusy(false)}};return <section className="page authPage"><div className="authCard"><span className="eyebrow">{mode==='login'?'WELCOME BACK':mode==='forgot'?'FORGOT PASSWORD':'JOIN THE FAMILY'}</span><h1>{mode==='login'?'Your Account':mode==='forgot'?'Reset Your Password':'Create an Account'}</h1><p>{mode==='forgot'?"Enter your email and we'll send you a link to set a new password.":'Sign in securely to view your orders and keep your account across devices.'}</p><form onSubmit={submit}>{mode==='signup'&&<input name="name" placeholder="Full name" value={form.name} onChange={change} required/>}{mode==='signup'&&<input name="mobile" type="tel" inputMode="tel" placeholder="Mobile number" value={form.mobile} onChange={change} maxLength="20" autoComplete="tel"/>}<input name="email" type="email" placeholder="Email address" value={form.email} onChange={change} required/>{mode!=='forgot'&&<input name="password" type="password" placeholder="Password" value={form.password} onChange={change} required minLength="6"/>}{mode==='login'&&<button type="button" className="textBtn" onClick={()=>setMode('forgot')}>Forgot password?</button>}<button className="primary wide" disabled={busy}>{busy?'Please wait…':mode==='login'?'Login':mode==='forgot'?'Send Reset Link':'Sign Up'}</button></form><button className="switch" onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'New here? Create an account':mode==='forgot'?'Back to login':'Already have an account? Login'}</button><button className="guest" onClick={()=>go('shop')}>Continue as guest</button></div></section>}
function Contact({instagram}){return <section className="page wrap contactPage"><span className="eyebrow">GET IN TOUCH</span><h1>Contact Us</h1><p>Choose whichever way is easiest for you — we're happy to help.</p><div className="contactOptions"><a className="contactCard whatsappCard" href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer"><WhatsIcon size={34}/><div><b>WhatsApp</b><span>Chat with us directly</span></div></a><a className="contactCard instaCard" href={instagram} target="_blank" rel="noreferrer"><InstaIcon size={30}/><div><b>Instagram</b><span>DM us @swetha_handmades</span></div></a></div></section>}
function About({go}){return <section className="page wrap aboutPage"><span className="eyebrow">THE SWETHA HANDMADES STORY</span><h1>Small details.<br/><em>Big feelings.</em></h1><p className="lead">Every box, album and keepsake is thoughtfully put together by hand — because the best gifts are little reminders of how much someone means to you.</p><div className="aboutCards"><div><Gift/><h3>Made by Hand</h3><p>Thoughtful creations prepared with care and attention to the little details.</p></div><div><Heart/><h3>Made Personal</h3><p>Personalised touches that turn a beautiful gift into your gift.</p></div><div><Sparkles/><h3>Made to Celebrate</h3><p>For birthdays, anniversaries, milestones and the lovely ordinary days in between.</p></div></div><button className="primary" onClick={()=>go('shop')}>Explore the Collection <ArrowRight size={17}/></button></section>}
function Privacy(){return <section className="page wrap legalPage"><span className="eyebrow">YOUR DATA</span><h1>Privacy Policy</h1><p><i>Last updated: 28 September 2026</i></p><p>Swetha Handmades ("we", "us") runs this website. This policy explains what personal data we collect, why, who helps us process it and how long we keep it, in line with India's Digital Personal Data Protection Act, 2023.</p>
 <h2>1. What we collect</h2><ul><li><b>Order details:</b> your name, mobile number, email (optional), delivery address, order notes and any personalisation text (name or message) you add.</li><li><b>Photos</b> you upload for a personalised gift.</li><li><b>Account details</b> if you sign up: email, name and mobile number. Your password is stored securely by our login provider and we never see it.</li><li><b>Payments:</b> we do not take payments on this website. Payment is arranged directly with you, and we only record the amount received.</li><li><b>On your device:</b> your cart and login session are kept in your browser's storage. We do not use advertising trackers.</li></ul>
 <h2>2. Why we use it</h2><p>To prepare, personalise and deliver your order; to contact you about your order and payment; to let you track orders and manage your account; and to keep the business and tax records we are required to keep. We do not sell your data or use it for marketing.</p>
 <h2>3. Who processes it for us</h2><ul><li><b>Supabase</b>: database, login and private photo storage.</li><li><b>Netlify</b>: website hosting.</li><li><b>Cloudflare Turnstile</b>: checks that orders are placed by a real person, to stop spam. It processes technical signals from your browser, not your order details.</li><li><b>EmailJS and Google (Gmail)</b>: order alert emails to us and account emails to you.</li><li><b>WhatsApp and Instagram (Meta)</b>: only if you choose to message us there; their own privacy policies apply.</li></ul><p>These providers may store data on servers outside India.</p>
 <h2>4. How long we keep it</h2><ul><li><b>Uploaded photos:</b> deleted automatically 30 days after your order is delivered or cancelled, and in any case within 90 days of upload. Only we can see them.</li><li><b>Photos sent on WhatsApp or Instagram:</b> we delete them from our devices once your order is complete.</li><li><b>Order records:</b> kept for as long as Indian tax and accounting law requires, even if you delete your account. They are then no longer linked to your account.</li><li><b>Your account:</b> until you delete it.</li></ul>
 <h2>5. Your rights</h2><p>You can ask to see, correct or delete your personal data, withdraw your consent, or raise a complaint. You can delete your account yourself on the <b>My Account</b> page. For anything else, contact us at <a href="mailto:swethahandmades1@gmail.com">swethahandmades1@gmail.com</a> or on <a href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer">WhatsApp</a>. If you are not satisfied with our response, you can complain to the Data Protection Board of India.</p>
 <h2>6. Security</h2><p>Your data is protected by access rules so that customers can only see their own orders and only we can see order details and uploaded photos. No system is perfectly secure, but we take reasonable steps to protect your data.</p>
 <h2>7. Children</h2><p>If you are under 18, please ask a parent or guardian to place the order.</p>
 <h2>8. Changes</h2><p>We may update this policy. The date at the top shows when it last changed.</p></section>}
function Terms({go}){return <section className="page wrap legalPage"><span className="eyebrow">THE FINE PRINT</span><h1>Terms &amp; Conditions</h1><p><i>Last updated: 28 September 2026</i></p><p>These terms apply when you browse swethahandmades.netlify.app or order from Swetha Handmades ("we", "us"). By placing an order you agree to them. Please also read our <button type="button" className="textBtn inlineLink" onClick={()=>go('privacy')}>Privacy Policy</button>.</p>
 <h2>1. Our products</h2><p>Every item is handmade, so colours, sizes and finishes may vary slightly from the photos. Photos are for illustration. Personalised items are made to the details you give us.</p>
 <h2>2. Placing an order</h2><ul><li>Placing an order on the website is a request to buy. Your order is accepted when we confirm it with you on WhatsApp, phone or email.</li><li>We may decline or cancel an order, for example if an item is unavailable, a price was shown incorrectly or we cannot reach you. If you have already paid, we will refund you in full.</li><li>Please give correct contact and delivery details. We are not responsible for delays caused by incorrect details.</li></ul>
 <h2>3. Prices and payment</h2><ul><li>Prices are in Indian Rupees (₹). The price charged is the one confirmed in your order.</li><li>We do not take payment on the website. After you order, we contact you to arrange payment and to confirm any delivery charges before you pay.</li><li>We start making your order once payment (or an agreed advance) has been received.</li></ul>
 <h2>4. Personalisation and photos</h2><ul><li>Please check names, messages and photos carefully before sending them. We will use them as provided and cannot be responsible for spelling or quality issues in what you send.</li><li>You confirm you have the right to use any photos you send us, and that they do not contain unlawful or offensive content. We may decline content we consider inappropriate.</li><li>Your order may be delayed until we receive the personalisation details or photos it needs.</li><li>Uploaded photos are handled as described in our Privacy Policy.</li></ul>
 <h2>5. Delivery</h2><ul><li>We will tell you the expected delivery or pickup date when we confirm your order. Dates are estimates and may be affected by couriers, weather or holidays.</li><li>Delivery areas and charges are confirmed with you before payment.</li><li>Please check your parcel on arrival.</li></ul>
 <h2>6. Cancellations</h2><ul><li>You may cancel for free before we have confirmed your order and started work on it.</li><li>Personalised or custom-made items cannot be cancelled or refunded once we have started making them, because they are made just for you.</li><li>To cancel, contact us on WhatsApp or email with your order ID.</li></ul>
 <h2>7. Damaged, wrong or faulty items</h2><p>If your order arrives damaged, faulty or not as ordered, please contact us within <b>48 hours</b> of delivery with your order ID and clear photos of the item and packaging. We will then offer a repair, replacement or refund as appropriate. We cannot accept returns for change of mind on personalised or custom-made items.</p>
 <h2>8. Refunds</h2><p>Approved refunds are made to the original payment method, or another method we agree with you, within 7 working days of approval.</p>
 <h2>9. Your account</h2><p>Keep your password private. You are responsible for activity on your account. You can delete your account at any time from the <b>My Account</b> page.</p>
 <h2>10. Use of the website</h2><p>Do not misuse the website: no false orders, automated or bulk orders, attempts to break its security, or copying of our photos and content without permission. All website content and product photos belong to Swetha Handmades unless stated otherwise.</p>
 <h2>11. Liability</h2><p>We take care with every order, but to the extent the law allows, our liability for any order is limited to the amount you paid for it. Nothing in these terms limits your rights under the Consumer Protection Act, 2019 or other Indian law.</p>
 <h2>12. Changes and governing law</h2><p>We may update these terms; the version shown when you order applies to that order. These terms are governed by the laws of India.</p>
 <h2>13. Contact us</h2><p>Questions or complaints: <a href="mailto:swethahandmades1@gmail.com">swethahandmades1@gmail.com</a> or <a href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer">WhatsApp</a>. Please include your order ID.</p></section>}
function NotFound({go}){return <section className="page wrap notFoundPage"><span className="eyebrow">404</span><h1>We couldn't find that page</h1><p>The link may be old or mistyped. Let's get you back to something lovely.</p><button className="primary" onClick={()=>go('shop')}>Browse Gifts <ArrowRight size={17}/></button><button className="textBtn" onClick={()=>go('home')}>Go to the homepage</button></section>}
function Footer({go,instagram,categories,setCategory}){return <footer><div className="wrap footGrid"><div><button className="brand footBrand" onClick={()=>go('home')}><span>Swetha</span><b>HANDMADES</b></button><p>Thoughtful handmade gifts for every special moment.</p></div><div><b>Shop</b>{categories.slice(0,4).map(c=><button key={c.id} onClick={()=>{setCategory(c.name);go('shop')}}>{c.name}</button>)}<button onClick={()=>{setCategory('All Products');go('shop')}}>All Products</button></div><div><b>Help</b><button onClick={()=>go('track')}>Track Order</button><button onClick={()=>go('contact')}>Contact</button><button onClick={()=>go('account')}>My Account</button><button onClick={()=>go('privacy')}>Privacy Policy</button><button onClick={()=>go('terms')}>Terms &amp; Conditions</button></div><div><b>Follow</b><a className="footerInsta" href={instagram} target="_blank" rel="noreferrer"><InstaIcon size={14}/> @swetha_handmades</a><p>♥ Made with love in India</p></div></div><div className="wrap copyright">© {new Date().getFullYear()} Swetha Handmades. All rights reserved. · <span className="poweredBy">Powered by <a href="https://www.smetechsolutions.com" target="_blank" rel="noreferrer">SME Tech Solutions</a></span></div></footer>}

function photoMessage({id,name,items}){return ["Hi Swetha Handmades! I'm sending the photos for my order.",`Order ID: ${id}`,name?`Name: ${name}`:null,`Items: ${(items||[]).map(i=>`${i.name} × ${i.qty}`).join(', ')}`,'My photos are attached.'].filter(Boolean).join('\n')}
function SendPhotosVia({order,instagram,flash}){const msg=photoMessage(order);const handle=(instagram||'').match(/instagram\.com\/([^/?#]+)/)?.[1]||'swetha_handmades';return <div className="instaPhotoBox"><b>Sending photos on WhatsApp or Instagram?</b><p>We've written the message with your order ID for you. Just attach your photos and send.</p><div className="contactIconsRow"><a className="uploadBtn" href={`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(msg)}`} target="_blank" rel="noreferrer"><WhatsIcon size={16}/> Send on WhatsApp</a><button type="button" className="uploadBtn" onClick={()=>{navigator.clipboard?.writeText(msg).then(()=>flash('Message copied. Paste it in Instagram and attach your photos'),()=>flash(`Please mention your order ID ${order.id} in your message`));window.open(`https://ig.me/m/${handle}`,'_blank','noopener')}}><InstaIcon size={16}/> Copy message &amp; open Instagram</button></div></div>}
function PhotoUpload({code,mobile}){const [st,setSt]=useState(null),[err,setErr]=useState(''),[busy,setBusy]=useState('');const refresh=async()=>{try{setSt(await api.photoStatus(code,mobile))}catch(e){console.error(e);setErr(e.message)}};useEffect(()=>{refresh()},[code,mobile]);if(!st||!st.items.length)return null;const upload=async(item,files)=>{const list=[...files].filter(f=>f.type.startsWith('image/')).slice(0,item.max_photos-item.uploaded);if(!list.length)return;setErr('');for(let i=0;i<list.length;i++){setBusy(`${item.product_name}: uploading photo ${i+1} of ${list.length}…`);try{if(list[i].size>25*1024*1024)throw new Error(`${list[i].name} is too large (max 25 MB)`);await api.uploadPhoto(code,mobile,item.line_no,await api.compressForUpload(list[i]))}catch(e){console.error(e);setErr(e.message);break}}setBusy('');await refresh()};return <div className="instaPhotoBox photoUploadBox"><b>Upload your personalised photos</b>{!st.open?<p>This order is closed, so photos can no longer be added.</p>:<><p>Add your photos here and we'll use them for your gift. You can also send them to us on WhatsApp or Instagram.</p>{st.items.map(it=><div key={it.line_no} className="photoItem"><span>{it.product_name}: <b>{it.uploaded} of {it.max_photos}</b> uploaded</span>{it.uploaded<it.max_photos&&<label className="uploadBtn"><Upload size={15}/> Choose photos<input type="file" accept="image/*" multiple hidden disabled={!!busy} onChange={e=>{upload(it,e.target.files);e.target.value=''}}/></label>}</div>)}{busy&&<p className="muted">{busy}</p>}{err&&<p className="photoError">{err}</p>}</>}</div>}
createRoot(document.getElementById('root')).render(<App/>);
